SET @prov_c:=(SELECT provincecode FROM sys_config LIMIT 1);

DROP TEMPORARY TABLE IF  EXISTS tx;
CREATE TEMPORARY TABLE IF NOT EXISTS tx ENGINE=MyISAM DEFAULT CHARSET=utf8 IGNORE  AS
SELECT p.hospcode,p.pid,p.CID,p.NAME,p.LNAME,p.BIRTH,p.SEX,p.NATION,p.check_typearea
,p.addr,p.check_vhid,p.DISCHARGE
FROM t_person_cid p
WHERE p.DISCHARGE in(9) ;

SELECT
h.hoscode,h.hosname,d.PID,d.CID,d.NAME,d.LNAME,d.SEX,d.BIRTH,d.addr,d.check_vhid,d.NATION
,d.check_typearea,d.DISCHARGE
FROM tx d 
INNER JOIN chospital h ON d.hospcode = h.hoscode
WHERE 1=1 {where}
